from collections import defaultdict

def fill_bounding_boxes(grid):
    positions = defaultdict(set)
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            positions[grid[r][c]].add((r, c))

    rows, cols = len(grid), len(grid[0])
    output = [[8]*cols for _ in range(rows)]

    for color, posset in positions.items():
        if color == 8:
            continue
        row_set = [r for r, c in posset]
        col_set = [c for r, c in posset]
        min_r, max_r = min(row_set), max(row_set)
        min_c, max_c = min(col_set), max(col_set)

        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                output[r][c] = color

    return output

